insert into public.dev_tracker (key, area, title, detail, status, next_step, sort_order, designed, built, tests_passed, merged, deployed, operational, awaiting) values
  ('elite-invitation', 'Elite Concierge', 'Elite Concierge by invitation only', 'Checkout and the database refuse Elite without an accepted invitation; membership page shows By Invitation Only.', 'deployed', 'Owner: test with a test account in a testing session.', 400, true, true, true, true, true, false, 'owner'),
  ('elite-pathways', 'Elite Concierge', 'Earned, expedited and founder admission pathways', 'Private screening, eligibility evaluation, automatic invitation, acceptance, founder invitations.', 'deployed', 'Owner: approve thresholds and milestones; test each pathway.', 401, true, true, true, true, true, false, 'owner'),
  ('elite-verification', 'Elite Concierge', 'Elite verification (owner review)', 'Private evidence storage, owner verify/reject/request info, statuses, appeals, retention dates.', 'deployed', 'Owner: test review flow. Automated third-party verification needs your approval of a provider.', 402, true, true, true, true, true, false, 'owner'),
  ('elite-badge', 'Elite Concierge', 'Elite verification badge', 'Gold rounded square with orange check; issued only by the system on activation; owner suspend/revoke.', 'deployed', 'Shown on the dashboard and Elite pages; adding it beside names across profiles and messages is next.', 403, true, true, true, true, true, false, 'owner'),
  ('elite-dashboard', 'Elite Concierge', 'Elite Concierge dashboard', 'Luxury dashboard; services not yet built are marked In preparation.', 'deployed', null, 404, true, true, true, true, true, false, 'owner'),
  ('elite-management', 'Owner Portal', 'Elite Management Center', 'Rules and thresholds, founder invitations, evidence review, decisions, badges, appeals, confidential notes, audit.', 'deployed', 'Owner: test.', 405, true, true, true, true, true, false, 'owner'),
  ('elite-expedited-payment', 'Elite Concierge', 'Expedited verification payment ($995 proposed)', 'Fee is configurable and inactive; payment checkout not built.', 'designed', 'Owner approval of the fee and terms, then build checkout.', 406, true, false, false, false, false, false, 'owner'),
  ('elite-business-connections', 'Elite Concierge', 'Elite Business Connections', null, 'designed', null, 407, true, false, false, false, false, false, null),
  ('elite-introductions', 'Elite Concierge', 'Elite Introductions and Elite Circle', null, 'designed', null, 408, true, false, false, false, false, false, null),
  ('elite-dating', 'Elite Concierge', 'Elite dating and relationships (30+ singles)', null, 'designed', null, 409, true, false, false, false, false, false, null),
  ('elite-revenue', 'Owner Portal', 'Elite revenue and analytics (separate reporting)', null, 'designed', null, 410, true, false, false, false, false, false, null),
  ('profile-photos', 'Members', 'Profile photographs and galleries (all members)', 'Upload, crop, reorder, captions, visibility, society galleries, moderation.', 'designed', null, 411, true, false, false, false, false, false, null)
insert into public.qa_features (key, department, title, tracker_key, href, purpose, steps, expected, sort) values
  ('elite-membership-label', 'account', 'Elite Concierge is by invitation only', (select key from public.dev_tracker where key = 'elite-invitation'), '/membership', 'Elite can''t be chosen or purchased without an accepted invitation.', array['Start a testing session and open Memberships.', 'Check Elite Concierge shows By Invitation Only and links to the Elite page.', 'With a test account that has no invitation, try to check out Elite (it should be refused).']::text[], 'Elite is shown as By Invitation Only; checkout is refused without an accepted invitation.', 1000),
  ('elite-page', 'account', 'Elite Concierge Society page', (select key from public.dev_tracker where key = 'elite-invitation'), '/elite', 'The public introduction: distinction, pathways, qualifications.', array['Open the Elite page on phone and computer.', 'Check only approved thresholds are shown.']::text[], 'Elevated, on-brand presentation; no unapproved amounts or confidential details.', 1010),
  ('elite-earned', 'account', 'Earned invitation (membership pathway)', (select key from public.dev_tracker where key = 'elite-pathways'), '/app/elite/eligibility', 'A member''s private progress and automatic invitation once every requirement is verified.', array['As a test member, answer the preliminary questions (Through my membership journey).', 'Submit an identity document and a qualification document.', 'In the Elite Management Center, mark both Verified.', 'Check the progress list; with milestones not yet met, no invitation issues.']::text[], 'Progress updates honestly; the invitation issues automatically only when every requirement is met; nothing is charged.', 1020),
  ('elite-expedited', 'account', 'Expedited verification pathway', (select key from public.dev_tracker where key = 'elite-pathways'), '/app/elite/eligibility', 'Preliminary screening first; expedited only for preliminarily qualified members.', array['As a test member, choose a pathway, answer Not yet, and confirm expedited isn''t offered.', 'Answer Yes with Expedited, submit documents, verify them as owner and Waive fee.', 'Confirm the invitation issues and can be accepted.']::text[], 'Expedited never bypasses identity or qualification; the fee stays inactive until approved; a waiver lets you test the flow.', 1030),
  ('elite-founder', 'admin', 'Founder''s discretionary invitation', (select key from public.dev_tracker where key = 'elite-management'), '/admin/elite', 'Invite an existing member or someone not yet a member, with a confidential reason.', array['Invite a test account by email with a reason.', 'Invite a new email, then register a test account with that email in a testing session.', 'Verify identity for each and confirm the invitation issues.']::text[], 'Thresholds are waived, identity is still required; reasons stay confidential; actions appear in the audit history.', 1040),
  ('elite-acceptance', 'financial', 'Invitation acceptance and Elite checkout (Stripe test mode)', (select key from public.dev_tracker where key = 'elite-invitation'), '/app/elite/eligibility', 'Accepting is free; Elite checkout opens only afterwards; payment activates the badge.', array['Accept the invitation as the test member.', 'Open Membership & billing, choose Elite Concierge and pay with 4242 4242 4242 4242.', 'Confirm the Elite dashboard opens and the badge is active.']::text[], 'No charge on acceptance; checkout succeeds in test mode; badge activates automatically.', 1050),
  ('elite-badge-qa', 'security', 'Elite badge issuance, suspension and revocation', (select key from public.dev_tracker where key = 'elite-badge'), '/admin/elite', 'Only the system and the owner control the badge; it reveals nothing confidential.', array['Tap the badge and read the explanation.', 'Suspend and then reactivate the badge in the Elite Management Center.', 'Revoke a candidate and confirm the dashboard closes for them.']::text[], 'Members can''t assign or remove badges; the explanation never reveals finances or pathway.', 1060),
  ('elite-privacy', 'security', 'Elite confidentiality', (select key from public.dev_tracker where key = 'elite-verification'), '/admin/elite', 'Verification documents and finances are visible only to the owner.', array['As a second test member, try to open another member''s eligibility page.', 'Confirm documents open only from the Elite Management Center, through expiring links.']::text[], 'Nothing confidential is visible to other members, Journey or connections.', 1070),
  ('elite-dashboard-qa', 'account', 'Elite Concierge dashboard', (select key from public.dev_tracker where key = 'elite-dashboard'), '/app/elite', 'The elevated Elite home, with honest status of each service.', array['As an activated Elite test member, open the dashboard on phone and computer.', 'Check unavailable services say In preparation.']::text[], 'Luxury presentation; nothing unavailable is presented as operational.', 1080),
  ('elite-appeals', 'admin', 'Elite review requests (appeals)', (select key from public.dev_tracker where key = 'elite-verification'), '/admin/elite', 'Members can request a review; the owner responds.', array['As a test member, send a review request.', 'Reconsider or decline it in the Elite Management Center.']::text[], 'The member sees the outcome on their eligibility page.', 1090)
