-- Elite Concierge Society: Development Tracker items and QA test plan (phase 1).
on conflict (key) do update set area = excluded.area, title = excluded.title, detail = excluded.detail, status = excluded.status, next_step = excluded.next_step, sort_order = excluded.sort_order,
  built = excluded.built, tests_passed = excluded.tests_passed, merged = excluded.merged, deployed = excluded.deployed, awaiting = excluded.awaiting, updated_at = now();
on conflict (key) do update set department = excluded.department, title = excluded.title, tracker_key = excluded.tracker_key, href = excluded.href, purpose = excluded.purpose, steps = excluded.steps, expected = excluded.expected, sort = excluded.sort;
